<?php namespace App\Filament\Resources;use App\Filament\Resources\StudentSupportCaseResource\Pages;use App\Filament\Resources\StudentSupportCaseResource\RelationManagers\ActionsRelationManager;use App\Models\StudentSupportCase;use Illuminate\Support\Facades\DB;use Filament\Forms;use Filament\Resources\Form;use Filament\Resources\Resource;use Filament\Resources\Table;use Filament\Tables;class StudentSupportCaseResource extends Resource{protected static ?string $model=StudentSupportCase::class;protected static ?string $navigationGroup='Воспитательная работа';protected static ?string $navigationLabel='Индивидуальное сопровождение';protected static ?string $pluralModelLabel='Индивидуальное сопровождение';public static function form(Form $f):Form{return $f->schema([Forms\Components\Select::make('student_id')->label('Студент')->options(fn()=>DB::table('students')->where('status','active')->orderBy('last_name')->get()->mapWithKeys(fn($s)=>[$s->id=>trim($s->last_name.' '.$s->first_name)]))->searchable()->required(),Forms\Components\Select::make('category')->label('Категория')->options(['individual'=>'Индивидуальная','attendance'=>'Посещаемость','behavior'=>'Поведение','social'=>'Социальная','psychological'=>'Психологическая','prevention'=>'Профилактика','family'=>'Семья','other'=>'Другое'])->required(),Forms\Components\Select::make('priority')->label('Приоритет')->options(['normal'=>'Обычный','high'=>'Высокий','critical'=>'Критический'])->required(),Forms\Components\Textarea::make('reason')->label('Основание')->required()->columnSpan('full'),Forms\Components\Textarea::make('plan')->label('План работы')->columnSpan('full'),Forms\Components\DatePicker::make('next_contact_on')->label('Следующий контакт')])->columns(2);}public static function table(Table $t):Table{return $t->columns([Tables\Columns\TextColumn::make('student_id')->label('Студент')->formatStateUsing(fn($id)=>($s=DB::table('students')->where('id',$id)->first())?trim($s->last_name.' '.$s->first_name):'—')->searchable(),Tables\Columns\BadgeColumn::make('category')->label('Категория'),Tables\Columns\BadgeColumn::make('priority')->label('Приоритет'),Tables\Columns\BadgeColumn::make('status')->label('Статус'),Tables\Columns\TextColumn::make('next_contact_on')->label('Контроль')->date('d.m.Y')])->actions([Tables\Actions\EditAction::make(),Tables\Actions\Action::make('close')->label('Закрыть')->requiresConfirmation()->visible(fn($r)=>$r->status!=='closed')->action(fn($r)=>$r->update(['status'=>'closed','closed_at'=>now()]))]);}public static function getRelations():array{return[ActionsRelationManager::class];}public static function getPages():array{return['index'=>Pages\ListStudentSupportCases::route('/'),'create'=>Pages\CreateStudentSupportCase::route('/create'),'edit'=>Pages\EditStudentSupportCase::route('/{record}/edit')];}public static function canViewAny():bool{$u=auth()->user();return $u&&($u->isSuperAdmin()||$u->hasRole('admin')||$u->canDo('upbringing.view'));}public static function canCreate():bool{$u=auth()->user();return $u&&($u->isSuperAdmin()||$u->hasRole('admin')||$u->canDo('upbringing.manage'));}public static function canEdit($record):bool{return static::canCreate();}public static function canDelete($record):bool{return false;}}